import csv
import io


def parse_csv_typed(csv_string):
    def infer(value):
        if value == '' or value == 'null' or value == 'None':
            return None
        if value == 'true':
            return True
        if value == 'false':
            return False
        # Numeric-looking values with leading zeroes stay strings.
        if value[0] == '0' and len(value) > 1 and value.isdigit():
            return value
        if value.isdigit():
            return int(value)
        # Handle negative integers/floats.
        if value[0] == '-' and len(value) > 1 and value[1:].replace('.', '', 1).isdigit():
            return float(value) if '.' in value else int(value)
        if value.replace('.', '', 1).isdigit():
            return float(value)
        return value

    reader = csv.reader(io.StringIO(csv_string))
    rows = [row for row in reader if any(field.strip() for field in row)]
    if not rows:
        return []

    headers = rows[0]
    return [
        {header: infer(value) for header, value in zip(headers, row)}
        for row in rows[1:]
    ]
